package org.apache.commons.io.input;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.io.PipedReader;
import java.io.PipedWriter;
import java.io.Reader;
import java.io.StringReader;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class ReaderInputStream_ESTest_test12 extends ReaderInputStream_ESTest_scaffolding {

    /**
     * A ReaderInputStream constructed with a null charset name falls back to the
     * default charset and starts in the open (not-closed) state.
     */
    @Test(timeout = 4000)
    public void constructorWithNullCharsetNameProducesOpenStream() throws Throwable {
        PipedReader sourceReader = new PipedReader();
        String nullCharsetName = null;

        ReaderInputStream readerInputStream = new ReaderInputStream(sourceReader, nullCharsetName);

        assertFalse("A newly constructed stream should not be closed", readerInputStream.isClosed());
    }
}
